!function(){"use strict";document.addEventListener("DOMContentLoaded",(function(){const t=document.getElementById("xero-floating-emojis");if(!t)return;const e=t.dataset.emoji||"😊";for(let n=0;n<15;n++){const n=document.createElement("div");n.className="xero-floating-emoji",n.textContent=e,n.style.left=100*Math.random()+"%",n.style.fontSize=20+30*Math.random()+"px",n.style.animationDuration=15+10*Math.random()+"s",n.style.animationDelay=5*Math.random()+"s",n.style.opacity=.5+.5*Math.random(),t.appendChild(n)}}))}();